-- Hypothetical monthly allocations and operational invoice ledger. Money: JPY millions.
CREATE TABLE finance_months (
 id TEXT PRIMARY KEY,
 finance_period_id TEXT NOT NULL REFERENCES finance_periods(id),
 month_index INTEGER NOT NULL CHECK(month_index BETWEEN 0 AND 11),
 revenue REAL NOT NULL CHECK(revenue>=0),
 cost_of_sales REAL NOT NULL CHECK(cost_of_sales>=0),
 sga_people REAL NOT NULL CHECK(sga_people>=0),
 sga_cloud REAL NOT NULL CHECK(sga_cloud>=0),
 sga_marketing REAL NOT NULL CHECK(sga_marketing>=0),
 sga_rent REAL NOT NULL CHECK(sga_rent>=0),
 sga_travel REAL NOT NULL CHECK(sga_travel>=0),
 sga_other REAL NOT NULL CHECK(sga_other>=0),
 version INTEGER NOT NULL DEFAULT 1,
 UNIQUE(finance_period_id,month_index)
);
CREATE TABLE finance_invoices (
 id TEXT PRIMARY KEY,
 finance_period_id TEXT NOT NULL REFERENCES finance_periods(id),
 kind TEXT NOT NULL CHECK(kind IN ('receivable','payable')),
 counterparty TEXT NOT NULL,
 issued_on TEXT NOT NULL,
 due_on TEXT,
 amount REAL NOT NULL CHECK(amount>0),
 version INTEGER NOT NULL DEFAULT 1,
 CHECK(due_on IS NULL OR due_on>=issued_on)
);
CREATE TABLE finance_settlements (
 id TEXT PRIMARY KEY,
 invoice_id TEXT NOT NULL REFERENCES finance_invoices(id),
 amount REAL NOT NULL CHECK(amount>0),
 settled_on TEXT NOT NULL,
 note TEXT NOT NULL,
 voided_on TEXT
);
CREATE INDEX finance_months_period ON finance_months(finance_period_id);
CREATE INDEX finance_invoices_period ON finance_invoices(finance_period_id);
CREATE INDEX finance_settlements_invoice ON finance_settlements(invoice_id);


-- Reconcile initial monthly profiles to current annual hypotheses without overwriting annual edits.
WITH weights AS MATERIALIZED (
 SELECT m.id,m.finance_period_id,CAST(p.revenue*1000000+0.5 AS INTEGER) AS target,
 CASE WHEN SUM(m.revenue) OVER (PARTITION BY m.finance_period_id)>0 THEN m.revenue/SUM(m.revenue) OVER (PARTITION BY m.finance_period_id) ELSE 1.0/12 END AS w
 FROM finance_months m JOIN finance_periods p ON m.finance_period_id=p.id
), raw AS MATERIALIZED (SELECT *,target*w AS value FROM weights), ranked AS MATERIALIZED (
 SELECT *,CAST(value AS INTEGER) AS base,ROW_NUMBER() OVER (PARTITION BY finance_period_id ORDER BY value-CAST(value AS INTEGER) DESC,id) AS rank,
 target-SUM(CAST(value AS INTEGER)) OVER (PARTITION BY finance_period_id) AS remainder FROM raw
)
UPDATE finance_months SET revenue=(SELECT (base+CASE WHEN rank<=remainder THEN 1 ELSE 0 END)/1000000.0 FROM ranked r WHERE r.id=finance_months.id);
WITH weights AS MATERIALIZED (
 SELECT m.id,m.finance_period_id,CAST(p.cost_of_sales*1000000+0.5 AS INTEGER) AS target,
 CASE WHEN SUM(m.cost_of_sales) OVER (PARTITION BY m.finance_period_id)>0 THEN m.cost_of_sales/SUM(m.cost_of_sales) OVER (PARTITION BY m.finance_period_id) ELSE 1.0/12 END AS w
 FROM finance_months m JOIN finance_periods p ON m.finance_period_id=p.id
), raw AS MATERIALIZED (SELECT *,target*w AS value FROM weights), ranked AS MATERIALIZED (
 SELECT *,CAST(value AS INTEGER) AS base,ROW_NUMBER() OVER (PARTITION BY finance_period_id ORDER BY value-CAST(value AS INTEGER) DESC,id) AS rank,
 target-SUM(CAST(value AS INTEGER)) OVER (PARTITION BY finance_period_id) AS remainder FROM raw
)
UPDATE finance_months SET cost_of_sales=(SELECT (base+CASE WHEN rank<=remainder THEN 1 ELSE 0 END)/1000000.0 FROM ranked r WHERE r.id=finance_months.id);
WITH categories AS MATERIALIZED (SELECT m.id,m.finance_period_id,j.key AS category,j.value AS weight FROM finance_months m,json_each(json_object('sga_people',m.sga_people,'sga_cloud',m.sga_cloud,'sga_marketing',m.sga_marketing,'sga_rent',m.sga_rent,'sga_travel',m.sga_travel,'sga_other',m.sga_other)) j), weights AS MATERIALIZED (
 SELECT c.*,CAST(p.sga*1000000+0.5 AS INTEGER) AS target,
 CASE WHEN SUM(weight) OVER (PARTITION BY finance_period_id)>0 THEN weight/SUM(weight) OVER (PARTITION BY finance_period_id) ELSE 1.0/72 END AS w
 FROM categories c JOIN finance_periods p ON c.finance_period_id=p.id
), raw AS MATERIALIZED (SELECT *,target*w AS value FROM weights), ranked AS MATERIALIZED (
 SELECT *,CAST(value AS INTEGER) AS base,ROW_NUMBER() OVER (PARTITION BY finance_period_id ORDER BY value-CAST(value AS INTEGER) DESC,id,category) AS rank,
 target-SUM(CAST(value AS INTEGER)) OVER (PARTITION BY finance_period_id) AS remainder FROM raw
)
UPDATE finance_months SET sga_people=(SELECT (base+CASE WHEN rank<=remainder THEN 1 ELSE 0 END)/1000000.0 FROM ranked r WHERE r.id=finance_months.id AND r.category='sga_people'),
sga_cloud=(SELECT (base+CASE WHEN rank<=remainder THEN 1 ELSE 0 END)/1000000.0 FROM ranked r WHERE r.id=finance_months.id AND r.category='sga_cloud'),
sga_marketing=(SELECT (base+CASE WHEN rank<=remainder THEN 1 ELSE 0 END)/1000000.0 FROM ranked r WHERE r.id=finance_months.id AND r.category='sga_marketing'),
sga_rent=(SELECT (base+CASE WHEN rank<=remainder THEN 1 ELSE 0 END)/1000000.0 FROM ranked r WHERE r.id=finance_months.id AND r.category='sga_rent'),
sga_travel=(SELECT (base+CASE WHEN rank<=remainder THEN 1 ELSE 0 END)/1000000.0 FROM ranked r WHERE r.id=finance_months.id AND r.category='sga_travel'),
sga_other=(SELECT (base+CASE WHEN rank<=remainder THEN 1 ELSE 0 END)/1000000.0 FROM ranked r WHERE r.id=finance_months.id AND r.category='sga_other');
